---@class UIMazeBagUseResultNode
---@field itemGo                        	UnityEngine.RectTransform               
---@field effects                       	UnityEngine.RectTransform               
---@field cfText4                       	UnityEngine.RectTransform                                                       
local UIMazeBagUseResultNode = Class("UIMazeBagUseResultNode")
function UIMazeBagUseResultNode:__init() 
    self._itemId = nil
    self._jsonData = nil
    self._index = nil
end

function UIMazeBagUseResultNode:__delete()
    self._itemId = nil
    self._jsonData = nil
    self._index = nil
end

function UIMazeBagUseResultNode:Awake()
end

function UIMazeBagUseResultNode:Start()
end

function UIMazeBagUseResultNode:Refresh(itemId, jsonData, index)
    self._itemId = checkNumber(itemId)
    if self._itemId == 0 then
        return
    end
    self._index = checkNumber(index)
    self._jsonData = jsonData

    self:FillEffect()
    KTool.SetActive(self.controller.gameObject, true)
end

function UIMazeBagUseResultNode:FillEffect()
    for i = 1, self.effects.childCount do
        local go = self.effects:GetChild(i - 1)
        KTool.SetActive(go, false)
    end

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._itemId, Constants.IDArea.Maze)
    if checkNumber(self._index) == 1 then
        CfUtils.FillText(self.cfText4, localize("使用了道具"))
        local itemGo = CfUtils.InstantiateGo(self.itemGo, self.effects)
        local scr = CfUtils.GetLuaScr(itemGo, UIMazeBagItemEffectNode)
        if scr then
            scr:Refresh(goodsVo)
        end
    elseif checkNumber(self._index) == 2 then
        CfUtils.FillText(self.cfText4, goodsVo.desc)
        if self._jsonData then
            if checkNumber(goodsVo.effectType) == Constants.GoodsEffectType.MazeCure then  --回复血量
                --如果是全体回复什么都不显示
                if checkNumber(goodsVo.targetType) == Constants.MazeItemTargetType.All then    
                else
                    for k, v in pairs(self._jsonData.cureRoles) do
                        local itemGo = self.itemGo.transform:Find("go"..k)
                        if not itemGo then
                            itemGo = CfUtils.InstantiateGo(self.itemGo, self.effects)
                            itemGo.name = "go"..k
                        end
    
                        local scr = CfUtils.GetLuaScr(itemGo, UIMazeBagItemEffectNode)
                        if scr then
                            scr:RefreshHero(v)
                        end
                    end
                end
                Events.Broadcast(Constants.EventNames.RefeshTeamMember, {levelType = Constants.IDType.QuestMaze})
            elseif checkNumber(goodsVo.effectType) == Constants.GoodsEffectType.MazeReborn then  --复活
                --如果是全体恢复都不显示
                if checkNumber(goodsVo.targetType) == Constants.MazeItemTargetType.All then
                else
                    for k, v in pairs(self._jsonData.rebornRoles) do
                        local itemGo = self.itemGo.transform:Find("go"..k)
                        if not itemGo then
                            itemGo = CfUtils.InstantiateGo(self.itemGo, self.effects)
                            itemGo.name = "go"..k
                        end
                        local scr = CfUtils.GetLuaScr(itemGo, UIMazeBagItemEffectNode)
                        if scr then
                            scr:RefreshHero(v)
                        end
                    end
                end
            elseif checkNumber(goodsVo.effectType) == Constants.GoodsEffectType.MazeDisperseCurses then  --驱散诅咒
                for k, v in pairs(self._jsonData.disperseCurses) do
                    local Curses = v
                    local itemGo = self.itemGo.transform:Find("go"..v)
                    if not itemGo then
                        itemGo = CfUtils.InstantiateGo(self.itemGo, self.effects)
                        itemGo.name = "go"..v
                    end

                    local curesData = GoodsConfMgr:GetInstance():GetGoodsVoById(v, Constants.IDArea.Maze)
                    local scr = CfUtils.GetLuaScr(itemGo, UIMazeBagItemEffectNode)
                    if scr then
                        scr:Refresh(curesData)
                    end
                end
            end
        end
    end
end

function UIMazeBagUseResultNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMazeBagUseResultNode
